import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord('A') + 1)
    return n - 1  # 0-based column

def row_idx(ref):
    return int(re.match(r'([A-Z]+)(\d+)', ref).group(2)) - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("ZIP entries:", names)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for sheet_path in sorted(n for n in names if re.match(r'xl/worksheets/sheet\d+\.xml', n)):
        print(f"\n--- {sheet_path} ---")
        root = ET.fromstring(z.read(sheet_path))
        sheet_data = root.find('m:sheetData', NS)
        rows = {}
        for row in sheet_data.findall('m:row', NS):
            r = int(row.get('r'))
            rows[r] = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None:
                    if t == 's':
                        val = shared[int(v.text)]
                    elif t == 'b':
                        val = v.text == '1'
                    elif t == 'inlineStr':
                        is_el = c.find('m:is', NS)
                        val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                    else:
                        val = v.text
                if val is not None:
                    rows[r][col_to_idx(ref)] = val
        for r in sorted(rows):
            print(r, rows[r])

import os, sys, zipfile, re, traceback
import xml.etree.ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
RNS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'

def col_letters(ref):
    m = re.match(r'[A-Z]+', ref)
    return m.group(0) if m else ''

def col_idx(letters):
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - 64)
    return n

def txt(el):
    if el is None:
        return ''
    return ''.join(t.text or '' for t in el.iter('{%s}t' % NS))

def main():
    print('CWD:', os.getcwd())
    try:
        print('LISTING:', os.listdir('.'))
    except Exception as e:
        print('LISTING ERROR:', repr(e))

    target = sys.argv[1] if len(sys.argv) > 1 else None
    candidates = []
    if target and os.path.isfile(target):
        candidates = [target]
    else:
        for root, dirs, files in os.walk('.'):
            dirs[:] = [d for d in dirs if not d.startswith('.')]
            for f in files:
                if f.lower() == 'budget.xlsx':
                    candidates.append(os.path.join(root, f))
    print('CANDIDATES:', candidates)
    if not candidates:
        print('NOT FOUND')
        return
    path = candidates[0]
    print('PARSING:', path)

    try:
        z = zipfile.ZipFile(path)
    except Exception as e:
        print('ZIP ERROR:', repr(e))
        return
    names = z.namelist()
    print('ZIP ENTRIES:', names)

    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root:
        rel_map[rel.get('Id')] = rel.get('Target')

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb_root.find('{%s}sheets' % NS):
        rid = sh.get('{%s}id' % RNS)
        tgt = rel_map.get(rid)
        if tgt:
            tgt = tgt.lstrip('/')
            if not tgt.startswith('xl/'):
                tgt = 'xl/' + tgt
        sheets.append((sh.get('name'), tgt))

    strings = []
    if 'xl/sharedStrings.xml' in names:
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.findall('{%s}si' % NS):
            strings.append(txt(si))

    grand_total = 0.0
    for sheet_name, target_path in sheets:
        print('=== SHEET:', sheet_name, target_path)
        if not target_path or target_path not in names:
            print('  (missing target)')
            continue
        root = ET.fromstring(z.read(target_path))
        sd = root.find('{%s}sheetData' % NS)
        grid = {}
        if sd is not None:
            for row in sd.findall('{%s}row' % NS):
                r = int(row.get('r'))
                for c in row.findall('{%s}c' % NS):
                    ref = c.get('r') or ''
                    cn = col_idx(col_letters(ref)) if ref else 0
                    t = c.get('t')
                    v_el = c.find('{%s}v' % NS)
                    raw = v_el.text if v_el is not None else None
                    if t == 's' and raw is not None:
                        val = strings[int(raw)]
                    elif t == 'inlineStr':
                        val = txt(c.find('{%s}is' % NS))
                    elif t == 'str':
                        val = raw
                    else:
                        val = raw
                    grid[(r, cn)] = val

        max_r = max((k[0] for k in grid), default=0)
        max_c = max((k[1] for k in grid), default=0)
        for r in range(1, max_r + 1):
            cells = []
            for cn in range(1, max_c + 1):
                v = grid.get((r, cn))
                cells.append('' if v is None else str(v))
            if any(cells):
                print('  R%03d: %s' % (r, ' | '.join(cells)))

        nums = []
        for (r, cn), v in grid.items():
            if v is not None and str(v).strip() != '':
                try:
                    nums.append((r, cn, float(v)))
                except (ValueError, TypeError):
                    pass
        if nums:
            sheet_sum = sum(x[2] for x in nums)
            grand_total += sheet_sum
            print('  SHEET NUMERIC SUM:', sheet_sum)
            print('  SHEET NUMERIC CELL COUNT:', len(nums))
    print('GRAND NUMERIC TOTAL:', grand_total)

try:
    main()
except SystemExit:
    raise
except Exception:
    traceback.print_exc()

